    14→			fallback: 'index.html',
    15→			precompress: false,
    16→			strict: true
    17→		}),
    18→		paths: {
    19→			// Set base path for GitHub Pages (empty for daemon/local)
    20→			base: basePath
    21→		}
    22→	}
    23→};
    24→
    25→export default config;
