@import "tailwindcss";

@import "tw-animate-css";
@import "./lib/ds/tokens.css";
@import "./lib/ds/animations.css";

@custom-variant dark (&:is(.dark *));

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.129 0.042 264.695);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.129 0.042 264.695);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.129 0.042 264.695);
  --primary: oklch(0.208 0.042 265.755);
  --primary-foreground: oklch(0.984 0.003 247.858);
  --secondary: oklch(0.968 0.007 247.896);
  --secondary-foreground: oklch(0.208 0.042 265.755);
  --muted: oklch(0.968 0.007 247.896);
  --muted-foreground: oklch(0.554 0.046 257.417);
  --accent: oklch(0.968 0.007 247.896);
  --accent-foreground: oklch(0.208 0.042 265.755);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.929 0.013 255.508);
  --input: oklch(0.929 0.013 255.508);
  --ring: oklch(0.704 0.04 256.788);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.984 0.003 247.858);
  --sidebar-foreground: oklch(0.129 0.042 264.695);
  --sidebar-primary: oklch(0.208 0.042 265.755);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.968 0.007 247.896);
  --sidebar-accent-foreground: oklch(0.208 0.042 265.755);
  --sidebar-border: oklch(0.929 0.013 255.508);
  --sidebar-ring: oklch(0.704 0.04 256.788);
}

.dark {
  --background: oklch(0.129 0.042 264.695);
  --foreground: oklch(0.984 0.003 247.858);
  --card: oklch(0.208 0.042 265.755);
  --card-foreground: oklch(0.984 0.003 247.858);
  --popover: oklch(0.208 0.042 265.755);
  --popover-foreground: oklch(0.984 0.003 247.858);
  --primary: oklch(0.929 0.013 255.508);
  --primary-foreground: oklch(0.208 0.042 265.755);
  --secondary: oklch(0.279 0.041 260.031);
  --secondary-foreground: oklch(0.984 0.003 247.858);
  --muted: oklch(0.279 0.041 260.031);
  --muted-foreground: oklch(0.704 0.04 256.788);
  --accent: oklch(0.279 0.041 260.031);
  --accent-foreground: oklch(0.984 0.003 247.858);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.551 0.027 264.364);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.208 0.042 265.755);
  --sidebar-foreground: oklch(0.984 0.003 247.858);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.279 0.041 260.031);
  --sidebar-accent-foreground: oklch(0.984 0.003 247.858);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.551 0.027 264.364);
}

@theme inline {
  /* ── Existing shadcn/ui radius tokens ── */
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* ── Existing shadcn/ui color tokens ── */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* ── Design System: 16 color tokens ── */
  --color-design-bg: var(--design-bg);
  --color-design-fg: var(--design-fg);
  --color-design-card: var(--design-card);
  --color-design-card-fg: var(--design-card-fg);
  --color-design-primary: var(--design-primary);
  --color-design-primary-fg: var(--design-primary-fg);
  --color-design-secondary: var(--design-secondary);
  --color-design-secondary-fg: var(--design-secondary-fg);
  --color-design-muted: var(--design-muted);
  --color-design-muted-fg: var(--design-muted-fg);
  --color-design-accent: var(--design-accent);
  --color-design-accent-fg: var(--design-accent-fg);
  --color-design-destructive: var(--design-destructive);
  --color-design-border: var(--design-border);
  --color-design-input: var(--design-input);
  --color-design-ring: var(--design-ring);

  /* ── Design System: 4 radius tokens ── */
  --radius-design-sm: var(--design-radius-sm);
  --radius-design-md: var(--design-radius-md);
  --radius-design-lg: var(--design-radius-lg);
  --radius-design-xl: var(--design-radius-xl);

  /* ── Design System: 7 spacing tokens ── */
  --spacing-design-xs: var(--design-spacing-xs);
  --spacing-design-sm: var(--design-spacing-sm);
  --spacing-design-md: var(--design-spacing-md);
  --spacing-design-lg: var(--design-spacing-lg);
  --spacing-design-xl: var(--design-spacing-xl);
  --spacing-design-2xl: var(--design-spacing-2xl);
  --spacing-design-3xl: var(--design-spacing-3xl);

  /* ── Design System: 7 z-index layers ── */
  --z-design-base: var(--design-z-base);
  --z-design-dropdown: var(--design-z-dropdown);
  --z-design-sticky: var(--design-z-sticky);
  --z-design-overlay: var(--design-z-overlay);
  --z-design-modal: var(--design-z-modal);
  --z-design-popover: var(--design-z-popover);
  --z-design-toast: var(--design-z-toast);

  /* ── Design System: 3 font families ── */
  --font-design-sans: var(--font-design-primary);
  --font-design-heading: var(--font-design-secondary);
  --font-mono: var(--font-design-mono);

  /* ── Design System: 7 status colors ── */
  --color-status-pending: var(--design-status-pending);
  --color-status-pending-fg: var(--design-status-pending-fg);
  --color-status-in-progress: var(--design-status-in-progress);
  --color-status-in-progress-fg: var(--design-status-in-progress-fg);
  --color-status-pending-review: var(--design-status-pending-review);
  --color-status-pending-review-fg: var(--design-status-pending-review-fg);
  --color-status-needs-work: var(--design-status-needs-work);
  --color-status-needs-work-fg: var(--design-status-needs-work-fg);
  --color-status-completed: var(--design-status-completed);
  --color-status-completed-fg: var(--design-status-completed-fg);
  --color-status-blocked: var(--design-status-blocked);
  --color-status-blocked-fg: var(--design-status-blocked-fg);
  --color-status-cancelled: var(--design-status-cancelled);
  --color-status-cancelled-fg: var(--design-status-cancelled-fg);

}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Design 04: Neo-Constructivist
 * Uncompromising visual authority through typography and geometry.
 * Pure black meeting signal red and yellow. Zero rounded corners.
 * oklch color space — maximalist contrast on minimalist palette.
 */

/* Dark theme (default) — propaganda poster on pure black */
[data-design="4"],
[data-design="4"][data-theme="dark"] {
  --design-bg: oklch(0.05 0 0);
  --design-fg: oklch(0.98 0 0);
  --design-card: oklch(0.1 0 0);
  --design-card-fg: oklch(0.96 0 0);
  --design-primary: oklch(0.58 0.22 28);
  --design-primary-fg: oklch(0.98 0 0);
  --design-secondary: oklch(0.82 0.17 95);
  --design-secondary-fg: oklch(0.08 0 0);
  --design-muted: oklch(0.15 0 0);
  --design-muted-fg: oklch(0.55 0 0);
  --design-accent: oklch(0.58 0.22 28);
  --design-accent-fg: oklch(0.98 0 0);
  --design-destructive: oklch(0.55 0.2 25);
  --design-warning: oklch(0.78 0.16 85);
  --design-border: oklch(0.25 0.02 28);
  --design-input: oklch(0.08 0 0);
  --design-ring: oklch(0.58 0.22 28);

  /* Zero radius — constructivist precision */
  --design-radius-sm: 0px;
  --design-radius-md: 0px;
  --design-radius-lg: 0px;
  --design-radius-xl: 0px;

  /* Extended tokens for constructivist effects */
  --design-border-weight: 2px;
  --design-grid-line: oklch(0.2 0 0);
  --design-watermark-opacity: 0.06;
}

/* Light theme — blueprint on cream */
[data-design="4"][data-theme="light"] {
  --design-bg: oklch(0.96 0.015 85);
  --design-fg: oklch(0.15 0 0);
  --design-card: oklch(0.93 0.012 85);
  --design-card-fg: oklch(0.18 0 0);
  --design-primary: oklch(0.52 0.22 28);
  --design-primary-fg: oklch(0.98 0 0);
  --design-secondary: oklch(0.72 0.17 95);
  --design-secondary-fg: oklch(0.1 0 0);
  --design-muted: oklch(0.9 0.01 85);
  --design-muted-fg: oklch(0.45 0 0);
  --design-accent: oklch(0.52 0.22 28);
  --design-accent-fg: oklch(0.98 0 0);
  --design-destructive: oklch(0.5 0.2 25);
  --design-warning: oklch(0.7 0.16 85);
  --design-border: oklch(0.8 0.01 85);
  --design-input: oklch(0.94 0.01 85);
  --design-ring: oklch(0.52 0.22 28);

  /* Zero radius — constructivist precision */
  --design-radius-sm: 0px;
  --design-radius-md: 0px;
  --design-radius-lg: 0px;
  --design-radius-xl: 0px;

  /* Extended tokens for light mode */
  --design-border-weight: 2px;
  --design-grid-line: oklch(0.85 0.01 85);
  --design-watermark-opacity: 0.04;
}

/* Selection — red highlight */
[data-design="4"] ::selection {
  background: color-mix(in oklch, var(--design-primary), transparent 30%);
  color: var(--design-fg);
}

/* Focus visible — sharp red outline */
[data-design="4"] :focus-visible {
  outline: 2px solid var(--design-ring);
  outline-offset: 2px;
}

/* Scrollbar — minimal, sharp */
[data-design="4"] ::-webkit-scrollbar {
  width: 8px;
}
[data-design="4"] ::-webkit-scrollbar-track {
  background: var(--design-bg);
}
[data-design="4"] ::-webkit-scrollbar-thumb {
  background: var(--design-border);
}
[data-design="4"] ::-webkit-scrollbar-thumb:hover {
  background: var(--design-primary);
}
[data-design="4"] {
  scrollbar-color: var(--design-border) var(--design-bg);
}

