    14→	let {
    15→		onclose = undefined as (() => void) | undefined,
    16→		onupdate = undefined as (() => void) | undefined
    17→	} = $props();
    18→
    19→	let noteContent = $state('');
    20→	let isSubmitting = $state('');
    21→	let error = $state('');
    22→
    23→	// Access task from store (bypasses Portal reactivity issues)
    24→	let task = $derived(taskDetailStore.task);
    25→
    26→	function close() {
    27→		taskDetailStore.close();
    28→		onclose?.();
    29→	}
    30→
