    32→	function handleOpenChange(newOpen: boolean) {
    33→		if (!newOpen) {
    34→			close();
    35→		}
    36→	}
    37→
    38→	async function handleStartTask() {
    39→		if (!task) return;
    40→
    41→		isSubmitting = true;
    42→		error = '';
    43→
    44→		try {
    45→			await startTask(task._ulid);
    46→			onupdate?.();
    47→			close();
    48→		} catch (err) {
    49→			error = err instanceof Error ? err.message : 'Failed to start task';
    50→		} finally {
    51→			isSubmitting = false;
    52→		}
    53→	}
    54→
    55→	async function handleAddNote() {
    56→		if (!task || !noteContent.trim()) return;
    57→
    58→		isSubmitting = true;
    59→		error = '';
    60→
    61→		try {
    62→			await addTaskNote(task._ulid, noteContent);
    63→			noteContent = '';
    64→			onupdate?.();
    65→		} catch (err) {
    66→			error = err instanceof Error ? err.message : 'Failed to add note';
    67→		} finally {
    68→			isSubmitting = false;
    69→		}
    70→	}
    71→
    72→	function formatDate(dateStr: string): string {
    73→		const date = new Date(dateStr);
    74→		return new Intl.DateTimeFormat('en-US', {
    75→			year: 'numeric',
    76→			month: 'short',
    77→			day: 'numeric',
    78→			hour: '2-digit',
    79→			minute: '2-digit'
    80→		}).format(date);
    81→	}
    82→
    83→	function getStatusColor(status: string): string {
    84→		const colors: Record<string, string> = {
    85→			pending: 'bg-gray-500',
    86→			in_progress: 'bg-blue-500',
    87→			pending_review: 'bg-yellow-500',
    88→			blocked: 'bg-red-500',
    89→			completed: 'bg-green-500',
    90→			cancelled: 'bg-gray-400'
    91→		};
    92→		return colors[status] || 'bg-gray-500';
    93→	}
