 2→	/**
 3→	 * Read-Only Banner Component
 4→	 *
 5→	 * Displays a banner indicating the app is in read-only mode
 6→	 * when running from a static export.
 7→	 *
 8→	 * AC: @gh-pages-export ac-15 - Data freshness indicator
 9→	 * AC: @gh-pages-export ac-14 - Validation badge
10→	 */
11→
12→	import { isStaticMode, getExportedAt, getSnapshotValidation } from '$lib/stores/mode.svelte';
13→	import { Badge } from '$lib/components/ui/badge';
14→	import { Button } from '$lib/components/ui/button';
15→	import { RefreshCw, CheckCircle, XCircle, BookOpen } from 'lucide-svelte';
16→
17→	// Format the exported timestamp for display
18→	function formatExportedAt(isoString: string | null): string {
19→		if (!isoString) return 'Unknown';
20→
21→		const date = new Date(isoString);
22→		const now = new Date();
23→		const diffMs = now.getTime() - date.getTime();
24→		const diffMins = Math.floor(diffMs / 60000);
25→		const diffHours = Math.floor(diffMins / 60);
26→		const diffDays = Math.floor(diffHours / 24);
27→
28→		// Show relative time for recent exports
29→		if (diffMins < 1) return 'Just now';
30→		if (diffMins < 60) return `${diffMins} minute${diffMins === 1 ? '' : 's'} ago`;
31→		if (diffHours < 24) return `${diffHours} hour${diffHours === 1 ? '' : 's'} ago`;
32→		if (diffDays < 7) return `${diffDays} day${diffDays === 1 ? '' : 's'} ago`;
33→
34→		// Show absolute date for older exports
35→		return date.toLocaleDateString(undefined, {
