 *
 * Uses standard color scheme:
 * - draft: zinc (dashed border)
 * - pending: amber
 * - ready: emerald
 * - assigned: blue
 * - running/in_progress: orange (animated pulse)
 * - orphaned: yellow (Lifeline disconnected, waiting for timeout)
 * - blocked: red
 * - completed: emerald
 * - failed: red
 */

type BadgeStatus =
  | 'draft'
  | 'pending'
  | 'ready'
  | 'assigned'
  | 'running'
  | 'in_progress'
  | 'orphaned'
  | 'blocked'
  | 'completed'
  | 'failed'
  | 'paused'
  | 'active'
  | 'archived';

interface Props {
  status: BadgeStatus;
  /** Size variant */
  size?: 'sm' | 'md';
}

